async function recordAuditEvent(params) {
  try {
    const db = await getDb();
    if (!db) return;
    await db.insert(auditLogs).values({
      actorUserId: params.actorUserId || null,
      organizationId: params.organizationId || null,
      actionType: params.actionType,
      resourceType: params.resourceType,
      resourceId: params.resourceId ? String(params.resourceId) : null,
      projectId: params.projectId || null,
      taskId: params.taskId || null,
      clientId: params.clientId || null,
      departmentId: params.departmentId || null,
      description: params.description || null,
      oldValues: params.oldValues || null,
      newValues: params.newValues || null,
      metadata: params.metadata || {},
      platform: params.platform || null,
      requestId: params.requestId || null,
      success: params.success !== false
      // default to true
    });
  } catch (error51) {
    console.error("Failed to record audit event:", error51);
  }
}

// server/auvryn/rbac.service.ts
var ROLE_HIERARCHY = {
  owner: 100,
  administrator: 90,
  director: 80,
  senior_manager: 70,
  manager: 60,
  team_lead: 50,
  senior_employee: 40,
  employee: 30,
  intern: 20,
  freelancer: 10
};
function canManageRole(actorRole, targetRole) {
  if (actorRole === "owner") return true;
  return ROLE_HIERARCHY[actorRole] > ROLE_HIERARCHY[targetRole];
}
async function enforceOrgPermission(userId, organizationId, requiredRoleLevel = 0) {
  const db = await getDb();
  if (!db) throw new TRPCError({ code: "INTERNAL_SERVER_ERROR", message: "Database not available" });
  const membershipList = await db.select().from(organizationMemberships).where(
    and(
      eq(organizationMemberships.userId, userId),
      eq(organizationMemberships.organizationId, organizationId)
    )
  );
  if (membershipList.length === 0) {
    throw new TRPCError({ code: "FORBIDDEN", message: "You are not a member of this organization." });
  }
  const membership = membershipList[0];
  const userRole = membership.accessRole;
  const userPower = ROLE_HIERARCHY[userRole] || 0;
  if (userPower < requiredRoleLevel) {
    throw new TRPCError({ code: "FORBIDDEN", message: "Insufficient permissions for this action." });
  }
  return { membership, userPower };
}

