      const workspaceId = req.headers["x-workspace-id"];
      if (!workspaceId) {
        return res.status(400).json({ error: "Workspace ID is required" });
      }
      const meeting = await MeetingsService.createMeeting({
        hostId: user.id,
        workspaceId,
        title,
        description,
        startTime,
        endTime,
        settings
      });
      res.status(201).json({ meeting });
