// server/subscriptions/entitlements.middleware.ts
function requireEntitlement(feature) {
  return async (req, res, next) => {
    try {
      const user = req.user;
      if (!user || !user.id) {
        res.status(401).json({
          error: "unauthorized",
          message: "Authentication required to access this resource"
        });
        return;
      }
      const orgId = req.headers["x-organization-id"] || req.headers["x-workspace-id"] || req.query.orgId || req.body && req.body.organizationId || null;
      const check3 = await EntitlementsService.checkEntitlement({
        userId: user.id,
        orgId,
        feature
      });
      if (!check3.allowed) {
        res.status(403).json({
          error: "quota_exceeded",
          feature: check3.feature,
          current: check3.current,
          limit: check3.limit,
          tier: check3.tier,
          resetDate: check3.resetDate,
          upgradeUrl: check3.upgradeUrl || "/pricing",
          message: `Your ${check3.tier} plan quota for ${check3.feature} has been reached (${check3.current}/${check3.limit}). Please upgrade at /pricing to continue.`
        });
        return;
      }
      req.entitlement = check3;
      next();
    } catch (err) {
      console.error(`[requireEntitlement:${feature}] Verification error:`, err);
      res.status(500).json({
        error: "entitlement_check_failed",
        message: "Failed to verify subscription entitlements."
      });
    }
  };
}

